import { sha256, parsePacketJSON } from './engine.js';
const $ = id => document.getElementById(id);
const CASES = [
  {file:'positive-gap.json',title:'共同能隙 · 完整计数与对称性',description:'4 维仿射源，目标秩 2。逐顶点检查正负形式，并核对对称性与选定框架的连接。'},
  {file:'periodic-gap.json',title:'周期源 · 恒等边界识别',description:'常数有限源，精确检查谱隔离、对称性与恒等周期识别。'},
  {file:'wrong-window.json',title:'错能窗控制 · 框架选择错误',description:'源保持不变，交换试探框架。检查表明正确的格式不能替代正确的能窗。'},
  {file:'overlap.json',title:'能区重叠 · 共同区间未获证',description:'各点的直接间隙不自动提供共同费米区间；所请求的固定切口必须通过整域检查。'},
  {file:'wrong-symmetry.json',title:'错表示控制 · 态身份连接错误',description:'谱计数成立，但提交的表示与源框架不匹配。接收器应拒绝该连接。'},
  {file:'malformed-source.json',title:'不完整源控制 · 缺失矩阵行',description:'矩阵形状与声明的完整维数不一致。输入应被拒绝，不能作为数学结论。'}
];
let packet=null,currentName='positive-gap.json',receipt=null,running=false,loadSequence=0;
const LABELS={source_dimensions_and_symmetry:'源矩阵维数与实对称性',complete_carrier:'完整载体与全部矩阵行',trial_full_rank:'完整试探框架的秩',spectral_counts:'闭域上的完整有序谱计数',symmetry:'对称性连接恒等式（条件检查）',periodicity:'周期边界识别'};
const REASONS={SIGNED_FORMS_UNRESOLVED:'严格符号条件未通过',TRIAL_NOT_FULL_RANK:'试探框架不具备完整秩',SYMMETRY_BINDING_INVALID:'对称性绑定条件不成立',PERIODICITY_IDENTITY_FAILED:'周期识别条件不成立',MATRIX_DIMENSION:'矩阵维数或完整行数不符',SOURCE_NOT_SYMMETRIC:'源系数不满足实对称性'};
function error(message){$('input-error').textContent=message||'';$('input-error').hidden=!message;}
function setPacket(value,name){packet=value;currentName=name;receipt=null;$('source-editor').value=JSON.stringify(value,null,2);$('summary-n').textContent=value?.source?.dimension??'—';$('summary-d').textContent=Array.isArray(value?.source?.parameters)?value.source.parameters.length:'—';$('summary-r').textContent=value?.request?.rank??'—';$('run-button').disabled=false;$('editor-message').textContent='';error('');$('result-content').hidden=true;$('result-empty').hidden=false;$('status-chip').textContent='等待运行';$('status-chip').className='status-chip idle';}
async function loadCase(index){const c=CASES[index];if(!c)return;const sequence=++loadSequence;try{$('run-button').disabled=true;const response=await fetch(new URL('./examples/'+c.file,import.meta.url));if(!response.ok)throw new Error('HTTP '+response.status);const value=parsePacketJSON(await response.text());if(sequence!==loadSequence)return;setPacket(value,c.file);$('case-description').textContent=c.description;}catch(e){if(sequence!==loadSequence)return;$('run-button').disabled=true;error('算例载入失败。请通过网站或本地 HTTP 服务打开页面，或直接导入 JSON 文件。');}}
function details(name,c){
  if(c.status==='NOT_REQUESTED')return '此输入未请求该项；报告不据此推断对应性质。';
  if(c.message)return c.message;
  if(name==='source_dimensions_and_symmetry')return `完整维数 ${c.dimension??packet?.source?.dimension??'—'}；仿射系数逐项检查。`;
  if(name==='complete_carrier')return '全部矩阵行来自同一声明源，未使用截断子矩阵冒充完整载体。';
  if(name==='trial_full_rank')return '正、负试探框架合并后，在完整载体上检查线性无关性。';
  if(name==='spectral_counts')return `实际检查 ${c.vertices_checked??0} 个闭立方体顶点；通过精确 LDLᵀ 主元验证符号。`;
  if(name==='symmetry')return '核对正交性、源系数对易、框架正交及 V E = E D 连接条件。';
  if(name==='periodicity')return '本配置支持恒等边界识别：相关仿射系数必须严格为零。';
  return '';
}
function makeCheck(name,c){const li=document.createElement('li'),icon=document.createElement('span'),body=document.createElement('span'),state=document.createElement('span'),detail=document.createElement('span');const pass=c.status==='PASS',skip=c.status==='NOT_REQUESTED';icon.className='check-icon'+(pass?'':skip?' unknown':' fail');icon.textContent=pass?'✓':skip?'—':'×';body.className='obligation-label';body.textContent=LABELS[name]||name;detail.className='obligation-detail';detail.textContent=details(name,c);body.append(detail);state.className='check-state'+(pass?'':skip?' unknown':' fail');state.textContent=pass?'PASS':skip?'未请求':'未通过';li.append(icon,body,state);return li;}
function render(r,elapsed){
  const status=r.status||'REJECTED',cls=status.toLowerCase(),cert=status==='CERTIFIED',unresolved=status==='UNRESOLVED';
  $('result-empty').hidden=true;$('result-content').hidden=false;$('status-chip').textContent=status;$('status-chip').className='status-chip '+cls;
  $('conclusion-box').className='conclusion-box '+cls;$('conclusion-icon').textContent=cert?'✓':unresolved?'?':'×';$('conclusion-label').textContent=status;
  const conclusion=r.conclusion;
  $('conclusion-title').textContent=cert?`已证明完整的 rank-${conclusion.rank} 共同能窗`:unresolved?'当前证明条件未能接收请求':'输入或提交的连接条件被拒绝';
  $('conclusion-description').textContent=cert?`在整个闭参数域，恰有 ${conclusion.rank} 个态位于下切口以下，其余 ${r.source.dimension-conclusion.rank} 个态位于上切口以上。`:unresolved?(r.reason_codes?.some(c=>['BROWSER_WALL_BUDGET','ARITHMETIC_LIMIT'].includes(c))?'浏览器计算预算已耗尽，未得出谱结论。请使用本地入口继续检查。':'未获证说明这些试探框架或充分界未通过；它本身不证明物理无隙。'):(r.error||r.reason_codes?.map(c=>REASONS[c]||c).join('；')||'输入未满足当前接收配置。');
  $('result-n').textContent=r.source?.dimension??'—';$('result-vertices').textContent=r.checks?.spectral_counts?.vertices_checked??'—';$('result-gap').textContent=cert?conclusion.gap_lower_bound:'—';$('result-time').textContent=elapsed<1000?`${Math.max(1,Math.round(elapsed))} ms`:`${(elapsed/1000).toFixed(2)} s`;
  const checks=Object.entries(r.checks||{});$('obligation-list').replaceChildren(...checks.map(([name,c])=>makeCheck(name,c)));$('obligation-count').textContent=`${checks.filter(([,c])=>c.status==='PASS').length} 项通过 / ${checks.length} 项报告`;
  $('result-source').textContent=r.source?.id||packet?.source?.id||'未接收';const ps=r.source?.parameters||packet?.source?.parameters||[];$('result-domain').textContent=ps.length?ps.map(p=>`${p} ∈ [0, 1]`).join('，'):'无自由参数（单个完整矩阵）';
  $('receipt-json').textContent=JSON.stringify({status:r.status,checks:r.checks,conclusion:r.conclusion,source:{id:r.source?.id,dimension:r.source?.dimension,parameters:r.source?.parameters},scope:r.scope},null,2);$('action-message').textContent='';
}
function verifyInWorker(input){return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});const timer=setTimeout(()=>{worker.terminate();resolve({schema:'source-bound-receipt-v1',status:'UNRESOLVED',checks:{},reason_codes:['BROWSER_WALL_BUDGET'],message:'Browser wall-time budget exhausted; no spectral conclusion follows.',scope:'Browser exact-reception time budget exhausted; this is not a proof of a physical gap closure.'});},15000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();if(e.data.error)reject(new Error(e.data.error));else resolve(e.data.receipt);};worker.onerror=e=>{clearTimeout(timer);worker.terminate();reject(new Error(e.message||'浏览器计算线程错误'));};worker.postMessage(input);});}
async function run(){if(!packet||running)return;const runPacket=structuredClone(packet),runName=currentName;running=true;for(const id of ['case-select','file-input','source-editor','apply-editor'])$(id).disabled=true;$('drop-zone').setAttribute('aria-disabled','true');error('');$('run-button').disabled=true;$('run-button').querySelector('span:nth-child(2)').textContent='正在精确检查…';$('status-chip').textContent='正在运行';$('status-chip').className='status-chip running';await new Promise(resolve=>setTimeout(resolve,30));const startedUTC=new Date().toISOString();const start=performance.now();try{receipt=await verifyInWorker(runPacket);receipt.input_sha256=await sha256(runPacket);receipt.client_execution={engine:'browser BigInt rational receiver v1',started_utc:startedUTC,input_file:runName,wall_ms:Math.round((performance.now()-start)*1000)/1000};render(receipt,performance.now()-start);}catch(e){error('本次运算未完成：'+e.message);$('status-chip').textContent='运行错误';$('status-chip').className='status-chip rejected';}finally{running=false;for(const id of ['case-select','file-input','source-editor','apply-editor'])$(id).disabled=false;$('drop-zone').removeAttribute('aria-disabled');$('run-button').disabled=false;$('run-button').querySelector('span:nth-child(2)').textContent='一键认证';}}
async function importFile(file){if(running){error('请等待本次运行完成后再更换输入。');return;}if(!file)return;++loadSequence;if(file.size>1000000){error('文件超过 1 MB。当前入口面向小型有限仿射源。');return;}try{const text=await file.text();const value=parsePacketJSON(text);setPacket(value,file.name);$('case-select').value='custom';$('case-description').textContent='自定义输入已载入。点击“一键认证”检查输入条件和完整谱计数。';}catch(e){error('无法解析 JSON：'+e.message);}}
$('run-button').addEventListener('click',run);$('case-select').addEventListener('change',e=>{if(e.target.value!=='custom')loadCase(Number(e.target.value));});$('file-input').addEventListener('change',e=>importFile(e.target.files[0]));
for(const type of ['dragenter','dragover'])$('drop-zone').addEventListener(type,e=>{e.preventDefault();$('drop-zone').classList.add('dragging');});for(const type of ['dragleave','drop'])$('drop-zone').addEventListener(type,e=>{e.preventDefault();$('drop-zone').classList.remove('dragging');if(type==='drop')importFile(e.dataTransfer.files[0]);});
$('apply-editor').addEventListener('click',()=>{if(running)return;++loadSequence;try{const value=parsePacketJSON($('source-editor').value);setPacket(value,'custom-input.json');$('case-select').value='custom';$('case-description').textContent='编辑后的自定义输入已载入。需重新运行以获得本次结果。';$('editor-message').textContent='已应用';}catch(e){$('editor-message').textContent='JSON 解析失败';error(e.message);}});
$('download-button').addEventListener('click',()=>{if(!receipt)return;const blob=new Blob([JSON.stringify(receipt,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`source-bound-${receipt.status.toLowerCase()}-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('action-message').textContent='报告已生成';});
$('copy-command').addEventListener('click',async()=>{const input=CASES.some(c=>c.file===currentName)?`examples/${currentName}`:'source.json';const command=`python -B run.py verify --input ${input} --out runs/new-report-directory`;try{await navigator.clipboard.writeText(command);$('action-message').textContent='已复制命令';}catch{$('action-message').textContent=command;}});
const opts=CASES.map((c,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=c.title;return o;});const custom=document.createElement('option');custom.value='custom';custom.textContent='已导入的自定义输入';custom.disabled=true;$('case-select').replaceChildren(...opts,custom);await loadCase(0);
